function main() {
  const tipos = db.select().from(tiposFeriado).all();
  const tipoPorChave = new Map(tipos.map((t) => [t.chave, t.id]));

  for (const f of FERIADOS) {
    const tipoFeriadoId = tipoPorChave.get(f.tipoChave);
    if (!tipoFeriadoId) {
      throw new Error(`Tipo de feriado "${f.tipoChave}" não encontrado — rode seed:tipos-feriado antes.`);
    }

    let fonte = db.select().from(fontes).where(eq(fontes.descricao, f.fonte.descricao)).get();
    if (!fonte) {
      const inserted = db
        .insert(fontes)
        .values({
          descricao: f.fonte.descricao,
          url: f.fonte.url,
          tipo: f.fonte.tipo,
          dataPublicacao: f.fonte.dataPublicacao,
        })
        .returning()
        .get();
      fonte = inserted;
      console.log(`  fonte criada: "${f.fonte.descricao.slice(0, 60)}..."`);
    }

    // Match por nome+abrangencia+uf+codigoIbge+mes+dia+regraCalculo (null-safe)
    // — sem incluir codigoIbge o upsert colidiria entre municípios diferentes
    // com o mesmo nome de feriado (ex.: dois municípios de RO com "Dia de São
    // João"). Sem incluir mes/dia/regraCalculo, o upsert colide entre feriados
    // DIFERENTES do MESMO município que compartilham um nome genérico de
    // fallback (ex.: duas datas de "Feriado Municipal" na mesma cidade,
    // usadas quando o documento-fonte não nomeia o motivo) — bug real
    // detectado nesta sessão: a segunda entrada sobrescrevia a primeira a
    // cada reseed, perdendo a data mais antiga silenciosamente.
    const condicaoCodigo = f.codigoIbge === null ? isNull(feriados.codigoIbge) : eq(feriados.codigoIbge, f.codigoIbge);
    const condicaoMes = f.mes === null ? isNull(feriados.mes) : eq(feriados.mes, f.mes);
    const condicaoDia = f.dia === null ? isNull(feriados.dia) : eq(feriados.dia, f.dia);
    const condicaoRegra = f.regraCalculo === null ? isNull(feriados.regraCalculo) : eq(feriados.regraCalculo, f.regraCalculo);
    const existente = db
      .select()
      .from(feriados)
      .where(
        and(
          eq(feriados.nome, f.nome),
          eq(feriados.abrangencia, f.abrangencia),
          eq(feriados.uf, f.uf),
          condicaoCodigo,
          condicaoMes,
          condicaoDia,
          condicaoRegra,
        ),
      )
      .get();

    const valores = {
      tipoFeriadoId,
      nome: f.nome,
      abrangencia: f.abrangencia,
      uf: f.uf,
      codigoIbge: f.codigoIbge,
      mes: f.mes,
      dia: f.dia,
      regraCalculo: f.regraCalculo,
      anoInicio: null,
      anoFim: null,
      fonteId: fonte.id,
      autor: f.autor,
      dataVerificacao: f.dataVerificacao,
      observacao: f.observacao,
      ativo: true as const,
    };

    if (existente) {
      db.update(feriados).set(valores).where(eq(feriados.id, existente.id)).run();
      console.log(`✔ atualizado: ${f.nome} (${f.abrangencia}/${f.uf})`);
    } else {
      db.insert(feriados).values(valores).run();
      console.log(`✔ inserido: ${f.nome} (${f.abrangencia}/${f.uf})`);
    }
  }

  console.log(`\nTotal processado: ${FERIADOS.length} feriados curados.`);
}

main();
sqlite.close();
